    <main class="main">
      <nav class="tabs">
        <button class="btn" data-mode="beginner">Beginner</button>
        <button class="btn" data-mode="intermediate">Intermediate</button>
        <button class="btn" data-mode="expert">Expert</button>
        <button class="btn" data-mode="custom">Custom</button>
      </nav>

      <div class="controls hidden" id="customControls">
        <label>Width:</label><input id="width" value="30">
        <label>Height:</label><input id="height" value="20">
